','',{version:3,sources:['webpack://./src/文字合并脚本/设置界面.vue'],names:[],mappings:'AAqOA,sCACE,kBACF,CAEA,mCACE,aACF,CAEA,iCACE,YAAa,CACb,kBAAmB,CACnB,OACF,CAEA,wDACE,cACF,CAEA,uCACE,cAAe,CACf,wBAAiB,CAAjB,gBACF,CAEA,oCACE,aAAc,CACd,gBAAiB,CACjB,iBACF,CAEA,qCACE,YAAa,CACb,qBAAsB,CACtB,QACF,CAEA,oCACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,0CACE,eAAgB,CAChB,gCACF,CAEA,oDACE,UAAW,CACX,WAAY,CACZ,6CAA8C,CAC9C,iBAAkB,CAClB,yCAA0C,CAC1C,gCACF,CAEA,6DACE,WAAY,CACZ,kBACF,CAEA,6BACE,aAAc,CACd,cAAe,CACf,gBAAiB,CACjB,mBAAoB,CACpB,iBACF,CAEA,8BACE,gBAAiB,CACjB,cAAe,CACf,iBAAkB,CAClB,cAAe,CACf,UAAW,CACX,eACF,CAEA,uCACE,WAAY,CACZ,kBACF,CAEA,qCACE,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,gBACF',sourcesContent:['<template>
  <div class="text-merge-settings">
    <div class="inline-drawer">
      <div class="inline-drawer-toggle inline-drawer-header">
        <b>文字合并脚本</b>
        <div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div>
      </div>
      <div class="inline-drawer-content">
        <div class="text-merge-block flex-container">
          <input v-model="settings.enabled" type="checkbox" />
          <label>启用文字合并</label>
        </div>

        <div class="text-merge-block">
          <label class="range-block-title">处理范围定位</label>
          <div class="range-block-inputs">
            <div class="range-input-group">
              <label>开始标记</label>
              <input
                v-model="settings.startMarker"
                type="text"
                class="text_pole"
                placeholder="留空则从头开始"
                :disabled="!settings.enabled"
              />
            </div>
            <div class="range-input-group">
              <label>结束标记</label>
              <input
                v-model="settings.endMarker"
                type="text"
                class="text_pole"
                placeholder="留空则处理到末尾"
                :disabled="!settings.enabled"
              />
            </div>
          </div>
          <small class="range-hint">支持正则表达式。使用 \n 表示换行。</small>
        </div>

        <div class="text-merge-block flex-container">
          <input v-model="settings.useRegexMarkers" type="checkbox" :disabled="!settings.enabled" />
          <label>启用正则表达式标记</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          开始标记和结束标记将作为正则表达式处理
        </small>

        <div class="text-merge-block flex-container">
          <input v-model="settings.enableEditProcessing" type="checkbox" :disabled="!settings.enabled" />
          <label>编辑后自动处理</label>
        </div>

        <div class="text-merge-block flex-container">
          <input
            v-model="settings.editOnlyLayer0"
            type="checkbox"
            :disabled="!settings.enabled || !settings.enableEditProcessing"
          />
          <label>编辑时仅处理第0层消息</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          编辑时将忽略范围标记，处理整个消息内容。此选项不影响流式或非流式生成。
        </small>

        <div class="text-merge-block flex-container">
          <input v-model="settings.useRandomMerge" type="checkbox" :disabled="!settings.enabled" />
          <label>使用随机合并算法</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          将随机选择段落和合并方向，避免产生规律性的文本结构
        </small>

        <div class="text-merge-block flex-container">
          <input v-model="settings.allowRemerge" type="checkbox" :disabled="!settings.enabled" />
          <label>允许重复合并</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          已合并的段落可能被再次合并，增加文本复杂度；关闭后，已合并的段落会被保护，不会被其他段落再次合并
        </small>

        <div class="text-merge-block">
          <label class="range-block-title">文本模式检测</label>
          <small class="range-hint" style="margin-top: -5px; margin-bottom: 10px">
            选择要检测和合并的文本模式类型（至少启用一种）
          </small>

          <div class="pattern-checkboxes">
            <div class="flex-container">
              <input
                v-model="settings.enableDescStartDialogEnd"
                type="checkbox"
                :disabled="!settings.enabled || isLastPattern('enableDescStartDialogEnd')"
              />
              <label>描述开头 + 对话结尾</label>
            </div>

            <div class="flex-container">
              <input
                v-model="settings.enableDialogStartDescEnd"
                type="checkbox"
                :disabled="!settings.enabled || isLastPattern('enableDialogStartDescEnd')"
              />
              <label>对话开头 + 描述结尾</label>
            </div>

            <div class="flex-container">
              <input
                v-model="settings.enableDialogDescDialog"
                type="checkbox"
                :disabled="!settings.enabled || isLastPattern('enableDialogDescDialog')"
              />
              <label>对话开头 + 中间描述 + 对话结尾</label>
            </div>

            <div class="flex-container">
              <input
                v-model="settings.enablePureDesc"
                type="checkbox"
                :disabled="!settings.enabled || isLastPattern('enablePureDesc')"
              />
              <label>单行都是描述</label>
            </div>
          </div>
        </div>

        <div class="text-merge-block">
          <label class="range-block-title">字符长度限制</label>
          <div class="range-input-group">
            <input
              v-model.number="settings.maxLineLength"
              type="number"
              class="text_pole"
              placeholder="0"
              min="0"
              :disabled="!settings.enabled"
            />
          </div>
          <small class="range-hint">
            跳过超过指定字符长度的行，不做任何处理。设置为0=无限制。
          </small>
        </div>

        <div class="text-merge-block">
          <label class="range-block-title">随机跳过范围</label>
          <div class="range-input-group">
            <input
              v-model="settings.skipRange"
              type="text"
              class="text_pole"
              placeholder="0"
              :disabled="!settings.enabled"
            />
          </div>
          <small class="range-hint">
            随机跳过指定数量的段落，不做任何处理。格式：单个数字（如 "3"）或范围（如 "1-3"）。设置为 "0"
            则不跳过。当跳过数量大于等于段落总数时，整层不做处理。
          </small>
        </div>

        <div class="text-merge-block flex-container">
          <input v-model="settings.enableNewlineCleanup" type="checkbox" :disabled="!settings.enabled" />
          <label>启用换行清除(you.com 4.6optk开启稳定性有提升)</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          将清除 AI_thinking_end 标记和 Oblivionis Round 注释之间的双换行
        </small>

        <div class="text-merge-block">
          <label class="range-block-title">换行清除楼层范围</label>
          <div class="range-input-group">
            <input
              v-model.number="settings.newlineCleanupFloorRange"
              type="number"
              class="text_pole"
              placeholder="-3"
              :disabled="!settings.enabled || !settings.enableNewlineCleanup"
            />
          </div>
          <small class="range-hint">
            设置处理的楼层范围。正数（如 6）表示从第 0 层到第 6 层；负数（如 -2）表示最新的 2
            层。设置为 0 表示仅处理第 0 层。默认值 -3 表示处理最新的 3 层消息。
          </small>
        </div>

        <div class="text-merge-block flex-container">
          <input v-model="settings.enableDebugLog" type="checkbox" :disabled="!settings.enabled" />
          <label>启用调试日志</label>
        </div>
        <small class="range-hint" style="margin-top: -5px; margin-left: 20px">
          将在浏览器控制台输出详细的合并过程日志
        </small>

        <div class="text-merge-block">
          <button class="menu_button" :disabled="!settings.enabled" @click="handleClearMemory">清理处理记录</button>
          <small class="range-hint">清除所有已处理消息的记录，允许重新处理</small>
        </div>

        <hr class="sysHR" />
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { storeToRefs } from 'pinia';
import { useSettingsStore } from './settings';

const settingsStore = useSettingsStore();
const { settings } = storeToRefs(settingsStore);

const isLastPattern = (patternKey: keyof typeof settings.value) => {
  const patterns = [
    settings.value.enableDescStartDialogEnd,
    settings.value.enableDialogStartDescEnd,
    settings.value.enableDialogDescDialog,
    settings.value.enablePureDesc,
  ];
  const enabledCount = patterns.filter(Boolean).length;
  return enabledCount === 1 && settings.value[patternKey] === true;
};

const handleClearMemory = () => {
  settingsStore.clearProcessedMemory();
  toastr.success('已清理所有处理记录');
};
</script>

<style scoped>
.text-merge-settings {
  margin-bottom: 10px;
}

.text-merge-block {
  margin: 10px 0;
}

.flex-container {
  display: flex;
  align-items: center;
  gap: 8px;
}

.flex-container input[type='checkbox'] {
  cursor: pointer;
}

.flex-container label {
  cursor: pointer;
  user-select: none;
}

.range-block-title {
  display: block;
  font-weight: bold;
  margin-bottom: 8px;
}

.range-block-inputs {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.range-input-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.range-input-group label {
  font-size: 0.9em;
  color: var(--SmartThemeBodyColor);
}

.range-input-group input.text_pole {
  width: 100%;
  padding: 6px;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
  background: var(--SmartThemeBlurTintColor);
  color: var(--SmartThemeBodyColor);
}

.range-input-group input.text_pole:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.range-hint {
  display: block;
  margin-top: 8px;
  font-size: 0.85em;
  color: var(--grey70);
  font-style: italic;
}

.menu_button {
  padding: 8px 16px;
  margin-top: 5px;
  border-radius: 4px;
  cursor: pointer;
  width: 100%;
  max-width: 200px;
}

.menu_button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pattern-checkboxes {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-left: 10px;
}
</style>
